import csv
import os

SCORES_FILE = "leaderboard.csv"

# ── File operations ────────────────────────────────────
def load_scores():
    scores = {}
    if not os.path.exists(SCORES_FILE):
        return scores
    with open(SCORES_FILE, "r") as f:
        reader = csv.reader(f)
        for row in reader:
            if len(row) == 2:
                name, score = row
                scores[name] = int(score)
    return scores

def save_scores(scores):
    with open(SCORES_FILE, "w", newline="") as f:
        writer = csv.writer(f)
        for name, score in scores.items():
            writer.writerow([name, score])

# ── Display ────────────────────────────────────────────
def show_leaderboard(scores, top_n=5):
    if not scores:
        print("  No scores yet.")
        return
    ranked = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    print(f"\n{'═'*28}")
    print(f"{'  LEADERBOARD':^28}")
    print(f"{'═'*28}")
    medals = ["🥇", "🥈", "🥉"]
    for i, (name, score) in enumerate(ranked[:top_n]):
        medal = medals[i] if i < 3 else f"#{i+1}"
        print(f"  {medal}  {name:<14} {score:>5}")
    print(f"{'═'*28}\n")

# ── Main ───────────────────────────────────────────────
def main():
    scores = load_scores()
    print("=== Score Tracker ===")
    print(f"Loaded {len(scores)} existing scores.\n")

    while True:
        print("1. Add score   2. Leaderboard   3. Clear mine   4. Quit")
        choice = input("Choice: ").strip()

        if choice == "1":
            name  = input("Your name: ").strip()
            score = int(input("Your score: "))
            if name in scores:
                if score > scores[name]:
                    print(f"  New personal best! {scores[name]} → {score}")
                    scores[name] = score
                else:
                    print(f"  Your best is still {scores[name]}. Keep trying!")
            else:
                scores[name] = score
                print(f"  Welcome, {name}! Score: {score}")

        elif choice == "2":
            show_leaderboard(scores)

        elif choice == "3":
            name = input("Your name: ").strip()
            if name in scores:
                del scores[name]
                print(f"  {name} removed.")
            else:
                print(f"  '{name}' not found.")

        elif choice == "4":
            save_scores(scores)
            print(f"Scores saved. Goodbye!")
            break
        else:
            print("  Invalid choice.")

main()

